function songCard(s){return `<button class="song" data-song="${s.id}"><span class="cover">${['♪','♬','♩'][s.id%3]}</span><div><h3>${s.name}${progress['s'+s.id]?' ✓':''}</h3><p>${s.level} · ${s.author}</p></div><span class="play">▷</span></button>`}
function render(){ $('#roadmap').innerHTML=exercises.slice(0,3).map((e,i)=>`<button class="lesson" data-exercise="${i}"><div class="card-top"><span class="step">0${i+1}</span><span class="pill">${progress['e'+i]?'已完成 ✓':i?'基础训练':'从这里开始'}</span></div><div class="lesson-icon">${e.icon}</div><h3>${e.name}</h3><p>${['找到 Do Re Mi，和键盘交个朋友','五指练习，找到自然的弹奏感觉','从均匀的四拍开始，感受音乐律动'][i]}</p><div class="card-footer">${i?'入门 · 约 5 分钟':'零基础 · 约 3 分钟'} <span>↗</span></div></button>`).join('');$('#featured').innerHTML=songs.slice(0,3).map(songCard).join('');$('#exercises').innerHTML=exercises.map((e,i)=>`<button class="exercise" data-exercise="${i}"><span class="step">0${i+1}</span><div><h3>${e.name}</h3><p>${e.desc}</p></div><span class="status">${progress['e'+i]?'已完成 ✓':'开始练习 →'}</span></button>`).join('');renderSongs()}
let level='全部';function renderSongs(){let q=$('#search').value.trim();const filtered=songs.filter(s=>(level==='全部'||level===s.level)&&s.name.includes(q));$('#songs').innerHTML=filtered.length?filtered.map(songCard).join(''):'<p class="description">没有找到这首曲子，换个关键词试试。</p>'}render();
function page(id){$$('.page').forEach(p=>p.classList.toggle('active',p.id===id));$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===id));$('#page-name').textContent={learn:'学习空间',library:'分级曲库',practice:'专项训练',free:'自由弹奏'}[id];if(id==='free')exit();window.scrollTo({top:0,behavior:'smooth'})}$$('nav button').forEach(b=>b.onclick=()=>page(b.dataset.page));$('#all-songs').onclick=()=>page('library');$('#search').oninput=renderSongs;$('#levels').onclick=e=>{if(!e.target.dataset.level)return;level=e.target.dataset.level;$$('#levels button').forEach(b=>b.classList.toggle('active',b===e.target));renderSongs()};
let ctx,master,held=new Map(),sustain=false,sustained=[],audioReady=false;function audio(){if(!ctx){ctx=new AudioContext();master=ctx.createGain();master.gain.value=.65;const comp=ctx.createDynamicsCompressor();master.connect(comp);comp.connect(ctx.destination)}if(ctx.state==='suspended')ctx.resume();return ctx}
function sound(m){audio();const g=ctx.createGain(),t=ctx.currentTime;g.connect(master);const tone=$('#tone').value;const partials=tone==='bell'?[[1,1],[2.76,.25],[5.4,.12]]:tone==='electric'?[[1,1],[2,.35],[3,.1]]:tone==='organ'?[[1,.6],[2,.3],[4,.1]]:[[1,1],[2,.3],[3,.14],[4,.05]];const os=partials.map(([ratio,amp])=>{const o=ctx.createOscillator(),v=ctx.createGain();o.frequency.value=440*Math.pow(2,(m-69)/12)*ratio;o.type='sine';v.gain.value=amp*.18;o.connect(v);v.connect(g);o.start(t);return o});g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(1,t+.012);g.gain.exponentialRampToValueAtTime(tone==='organ'?.75:.14,t+(tone==='bell'?2.2:1.8));let stopped=false;return ()=>{if(stopped)return;stopped=true;const now=ctx.currentTime;g.gain.cancelScheduledValues(now);g.gain.setTargetAtTime(.0001,now,tone==='bell'?.25:.12);os.forEach(o=>o.stop(now+1.5));setTimeout(()=>g.disconnect(),1600)}}
function press(m,source){if(held.has(source))return;held.set(source,{m,stop:sound(m)});els[m]?.classList.add('pressed');if(!demoing&&(!document.body.classList.contains('immersed')||roomPlaying))judge(m)}function release(source){const v=held.get(source);if(!v)return;held.delete(source);if(sustain)sustained.push(v.stop);else v.stop();if(![...held.values()].some(x=>x.m===v.m))els[v.m]?.classList.remove('pressed')}
function allOff(){for(const k of [...held.keys()])release(k);sustain=false;sustained.splice(0).forEach(f=>f())}
window.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||$('#help-dialog').open)return;if(document.body.classList.contains('immersed')&&!roomPlaying&&!demoing)return;const k=e.key.toLowerCase();if(k===' '){e.preventDefault();sustain=true;return}if(keys[k]!==undefined){e.preventDefault();if(!e.repeat)press(keys[k],k)}});window.addEventListener('keyup',e=>{if(e.key===' '){sustain=false;sustained.splice(0).forEach(f=>f())}release(e.key.toLowerCase())});window.addEventListener('blur',allOff);document.addEventListener('visibilitychange',()=>{if(document.hidden){allOff();stopDemo();stopMetro()}});$$('.key').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);press(+b.dataset.note,'p'+e.pointerId)};b.onpointerup=b.onpointercancel=e=>release('p'+e.pointerId)});$('#volume').oninput=e=>{audio();master.gain.setTargetAtTime(+e.target.value/100,ctx.currentTime,.02)};
let training=null,index=0,attempts=0,correct=0,demoing=false,demoTimers=[],beatTimer=null,beatCount=0,rhythmStart=0,lockedBpm=80;
function bpm(){let n=Math.max(40,Math.min(180,Number($('#bpm').value)||80));$('#bpm').value=n;return n}function tick(accent){audio();const o=ctx.createOscillator(),g=ctx.createGain(),t=ctx.currentTime;o.frequency.value=accent?1200:850;g.gain.setValueAtTime(.09,t);g.gain.exponentialRampToValueAtTime(.001,t+.045);o.connect(g);g.connect(master);o.start(t);o.stop(t+.05);setTimeout(()=>g.disconnect(),100)}function startMetro(){stopMetro();lockedBpm=bpm();beatCount=0;$('#metronome').classList.add('on');const beat=()=>{tick(beatCount%4===0);beatCount++};beat();beatTimer=setInterval(beat,60000/lockedBpm)}function stopMetro(){clearInterval(beatTimer);beatTimer=null;$('#metronome').classList.remove('on')}$('#metronome').onclick=()=>{if(training?.rhythm){toast('节奏练习会自动控制节拍器');return}beatTimer?stopMetro():startMetro()};$('#bpm').onchange=()=>{bpm();if(training?.rhythm&&roomPlaying)runLesson(training,training.key);else if(beatTimer)startMetro()};
function runLesson(item,key){stopDemo();stopMetro();allOff();training={...item,key};index=attempts=correct=0;$('#trainer').hidden=false;$('#mode-title').textContent=item.name;$('#mode-subtitle').textContent=item.rhythm?'跟拍训练':'跟弹练习';$('#instruction').textContent=item.tip;$('#feedback').textContent='跟随高亮音符，按下对应按键';if(item.rhythm){startMetro();rhythmStart=performance.now()+4*60000/lockedBpm;$('#feedback').textContent='预备四拍，随后每拍弹一个音'}draw();$('.piano-panel').scrollIntoView({behavior:'smooth',block:'nearest'})}
function draw(){if(typeof refreshFalls==='function')refreshFalls();$('#note-track').innerHTML=training.notes.map((m,i)=>`<div class="note-chip ${i<index?'done':i===index?'current':''}"><b>${solfege[whites.indexOf(m)]||'♯'}</b><small>${Object.keys(keys).find(k=>keys[k]===m)?.toUpperCase()}</small></div>`).join('');$$('.key').forEach(b=>b.classList.toggle('target',+b.dataset.note===training.notes[index]));$('#score').textContent=`${index} / ${training.notes.length} 音符 · ${attempts?Math.round(correct/attempts*100):100}% 准确`;const chip=$('.note-chip.current');if(chip)$('#note-track').scrollLeft=Math.max(0,chip.offsetLeft-$('#note-track').offsetLeft-130)}
function judge(m){if(!training||index>=training.notes.length||demoing)return;if(training.rhythm&&performance.now()<rhythmStart-180){$('#feedback').textContent='先听完四拍预备';return}attempts++;if(m!==training.notes[index]){$('#feedback').textContent='再试一次，看看高亮琴键的位置';draw();return}if(training.rhythm){const beat=60000/lockedBpm;const delta=Math.abs(performance.now()-(rhythmStart+index*beat));if(delta>beat*.38){$('#feedback').textContent='音高对了，下一拍再弹（已重新对齐节拍）';rhythmStart+=Math.max(1,Math.ceil((performance.now()-(rhythmStart+index*beat))/beat))*beat;draw();return}}index++;correct++;$('#feedback').textContent=['很好，继续。','就是这个音！','放松手指，慢慢来。'][index%3];draw();if(index===training.notes.length){progress[training.key]={accuracy:Math.round(correct/attempts*100),date:Date.now()};save();render();stopMetro();completeRoom();$('#feedback').textContent=`✓ 完成！准确率 ${Math.round(correct/attempts*100)}%，可以再练一次或试试下一课。`;toast('又前进了一小步，练习已完成！')}}
function stopDemo(){demoTimers.forEach(clearTimeout);demoTimers=[];for(const k of [...held.keys()])if(String(k).startsWith('demo'))release(k);demoing=false;$('#demo').textContent='▷ 听示范'}function exit(){stopDemo();stopMetro();allOff();training=null;$('#trainer').hidden=true;$('#mode-title').textContent='自由探索';$('#mode-subtitle').textContent='试着按下 A，弹响中央 C';$$('.key').forEach(b=>b.classList.remove('target'))}
$('#start-learning').onclick=()=>start(exercises[0],'e0');document.addEventListener('click',e=>{const ex=e.target.closest('[data-exercise]'),s=e.target.closest('[data-song]');if(ex)start(exercises[+ex.dataset.exercise],'e'+ex.dataset.exercise);if(s)start(songs[+s.dataset.song],'s'+s.dataset.song)});$('#restart').onclick=()=>training&&runLesson(training,training.key);$('#exit-training').onclick=exit;$('#demo').onclick=()=>{if(!training)return;if(demoing){stopDemo();if(training.rhythm)runLesson(training,training.key);return}stopMetro();allOff();demoing=true;$('#demo').textContent='■ 停止示范';$('#feedback').textContent='先听一遍，留意琴键的位置';const delay=60000/bpm();training.notes.forEach((m,i)=>{demoTimers.push(setTimeout(()=>press(m,'demo'+i),i*delay));demoTimers.push(setTimeout(()=>release('demo'+i),i*delay+delay*.8))});demoTimers.push(setTimeout(()=>{stopDemo();if(training.rhythm)runLesson(training,training.key);else $('#feedback').textContent='轮到你了，跟着高亮音符弹奏'},training.notes.length*delay))};$('#help').onclick=()=>{allOff();$('#help-dialog').showModal()};$('#close-help').onclick=()=>$('#help-dialog').close();let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
